 configured=true;
 pendingConfigure=sourceEpoch;
 pendingToolFactory=openToolWorld;
 if(boundary) {
  pendingBoundary=createPendingHostBoundary(boundary);
  if(!pendingBoundary)throw Error('pending fixture boundary custody unavailable');
